+	"errors"
+	"fmt"
+	"hash/crc32"
+	"io"
+	"os"
+)
+
+// WAL record types.
+const (
+	recBegin    byte = 1
+	recSet      byte = 2
+	recDelete   byte = 3
+	recCommit   byte = 4
+	recRollback byte = 5
+)
+
+// walMagic prefixes every WAL frame (ASCII "KVWL").
+const walMagic uint32 = 0x4B56574C
+
+const (
+	walHeaderLen = 4 + 4 + 4 // magic + crc32 + payloadLen
+	walMaxKey    = 1 << 20   // 1 MiB
+	walMaxValue  = 1 << 30   // 1 GiB
