+	binary.LittleEndian.PutUint64(payload[0:8], txID)
+	payload[8] = recType
+	off := 9
+	binary.LittleEndian.PutUint32(payload[off:off+4], uint32(len(key)))
+	off += 4
+	copy(payload[off:], key)
+	off += len(key)
