+				return abortRecovery(path, commitEnd, goodEnd-n, res, warning)
+			}
+			res.committed[fr.txID] = ops
+			delete(pending, beginID)
+			finished[beginID] = true
+			commitEnd = goodEnd
+		case recRollback:
+			if len(fr.value) != 8 {
+				warning = fmt.Errorf("%w: malformed rollback frame", ErrWALCorrupt)
+				return abortRecovery(path, commitEnd, goodEnd-n, res, warning)
