+package kvstore
+
+import (
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"os"
+	"sort"
+	"sync"
+)
+
+const walFileName = "wal.log"
+
+var (
+	// ErrKeyNotFound is returned when a key has no visible live version.
+	ErrKeyNotFound = errors.New("kvstore: key not found")
+	// ErrWriteConflict is returned on the first-committer-wins conflict check.
+	ErrWriteConflict = errors.New("kvstore: write conflict")
+	// ErrReadOnlyTx is returned when a read-only transaction performs a write.
+	ErrReadOnlyTx = errors.New("kvstore: transaction is read-only")
+	// ErrTxFinished is returned when a finished transaction is used again.
+	ErrTxFinished = errors.New("kvstore: transaction already finished")
+	// ErrClosed is returned after the engine has been closed.
+	ErrClosed = errors.New("kvstore: engine closed")
+	// ErrWALCorrupt signals a CRC/frame damage; the tail has been truncated.
+	ErrWALCorrupt = errors.New("kvstore: corrupt WAL tail truncated")
+
+	errTruncated = errors.New("truncated frame")
+	errCorrupt   = errors.New("corrupt frame")
+)
+
+// Options configures an Engine.
+type Options struct {
+	// SyncWAL forces an fsync on every WAL append (including commit).
+	SyncWAL bool
+}
+
+// DefaultOptions fsyncs the WAL at transaction commit for durability.
+func DefaultOptions() Options { return Options{SyncWAL: true} }
+
+// record is one MVCC version of a key. Version chains are ordered newest
+// first. deletedTxID is set to the commit id of the transaction that
+// superseded this version (0 while it is the newest version).
+type record struct {
+	key         string
+	value       []byte
+	createdTxID uint64 // commit id that installed this version
+	deletedTxID uint64 // commit id that superseded it (0 if still head)
+	isDeleted   bool   // soft-delete tombstone
+}
+
+// Engine is an embedded MVCC key-value store with WAL durability.
+type Engine struct {
+	mu      sync.RWMutex
+	walMu   sync.Mutex // serializes all WAL appends
+	wal     *wal
+	closed  bool
+
+	nextID    uint64                // global monotonic timestamp allocator
+	versions  map[string][]*record  // key -> version chain (newest first)
+	active    map[uint64]*Tx        // active transaction tracker (begin id)
+	watermark uint64                // smallest active begin id; 0 when idle
+
+	syncWAL bool
+}
+
+// Open opens (or creates) an engine backed by a WAL in dirPath.
+// A non-nil warning indicates that a damaged WAL tail was detected and
+// truncated to the last valid commit point; the engine is still usable.
+func Open(dirPath string) (*Engine, error) {
+	return OpenWithOptions(dirPath, DefaultOptions())
+}
+
+// OpenWithOptions opens an engine with explicit Options.
+func OpenWithOptions(dirPath string, opts Options) (*Engine, error) {
+	if err := os.MkdirAll(dirPath, 0o755); err != nil {
+		return nil, err
+	}
+	w, err := openWAL(dirPath, opts.SyncWAL)
+	if err != nil {
+		return nil, err
+	}
+	e := &Engine{
+		wal:     w,
+		nextID:  1,
+		versions: make(map[string][]*record),
+		active:   make(map[uint64]*Tx),
+		syncWAL: opts.SyncWAL,
+	}
