+// Options configures an Engine.
+type Options struct {
+	// SyncWAL fsyncs the WAL on every commit when true (default).
+	SyncWAL bool
+}
+
+// DefaultOptions returns durable settings (WAL synced per commit).
+func DefaultOptions() Options {
+	return Options{SyncWAL: true}
+}
