+func (t *Tx) Delete(key string) error {
+	if err := t.checkWrite(); err != nil {
+		return err
+	}
+	t.writes[key] = txWrite{isDelete: true}
+
+	e := t.engine
+	e.walMu.Lock()
+	err := e.wal.append(t.beginID, recDelete, key, nil)
+	e.walMu.Unlock()
+	if err != nil {
+		delete(t.writes, key)
+		return err
+	}
+	return nil
+}
+
+func (t *Tx) checkWrite() error {
+	e := t.engine
+	e.mu.RLock()
+	defer e.mu.RUnlock()
+	if e.closed {
+		return ErrEngineClosed
+	}
+	if t.done {
+		return ErrTxClosed
+	}
+	if t.readOnly {
+		return ErrReadOnlyTx
+	}
+	return nil
+}
+
+// Commit makes buffered writes globally visible.
+//
+// Ordering is strictly: WAL TxCommit frame + fsync first, then publication
+// into the in-memory index. Write-write conflicts use first-committer-wins:
+// if any touched key gained a committed version at or after this snapshot,
+// ErrWriteConflict is returned and the transaction is auto-rolled-back.
+func (t *Tx) Commit() error {
+	e := t.engine
+
+	e.mu.Lock()
+	if e.closed {
+		e.mu.Unlock()
+		return ErrEngineClosed
+	}
+	if t.done {
+		e.mu.Unlock()
+		return ErrTxClosed
+	}
+
+	if t.readOnly {
+		t.done = true
+		delete(e.active, t.beginID)
+		e.mu.Unlock()
+		return nil
+	}
+
+	// Conflict detection: latest committed version newer than snapshot.
+	for key := range t.writes {
+		chain := e.versions[key]
+		if len(chain) > 0 && chain[0].createdTxID >= t.beginID {
+			t.done = true
+			delete(e.active, t.beginID)
+			e.mu.Unlock()
+			// Best-effort rollback record; failure is irrelevant to outcome.
+			e.logRollback(t.beginID)
+			return ErrWriteConflict
+		}
+	}
+
+	commitID := e.nextTS
+	e.nextTS++
+	e.mu.Unlock()
+
+	// Durability barrier: commit record must hit stable storage first.
+	idBuf := make([]byte, 8)
+	binary.LittleEndian.PutUint64(idBuf, t.beginID)
+	e.walMu.Lock()
+	if err := e.wal.append(commitID, recCommit, "", idBuf); err != nil {
+		e.walMu.Unlock()
+		e.mu.Lock()
+		t.done = true
+		delete(e.active, t.beginID)
+		e.mu.Unlock()
+		return err
+	}
+	e.walMu.Unlock()
+
+	// Publish under the write lock, coalescing repeated writes per key.
+	e.mu.Lock()
+	t.done = true
+	delete(e.active, t.beginID)
+
+	keys := make([]string, 0, len(t.writes))
+	for key := range t.writes {
+		keys = append(keys, key)
+	}
+	// Deterministic order is not required for correctness, but keeps chains tidy.
+	sortStrings(keys)
+	for _, key := range keys {
+		w := t.writes[key]
+		chain := e.versions[key]
+		if len(chain) > 0 {
+			chain[0].deletedTxID = commitID
+		}
+		r := &record{
+			key:         key,
+			createdTxID: commitID,
+			isDeleted:   w.isDelete,
+		}
+		if !w.isDelete {
+			r.value = append([]byte(nil), w.value...)
+		}
+		e.versions[key] = append([]*record{r}, chain...)
+	}
+	e.mu.Unlock()
+	return nil
+}
+
+// Rollback discards all buffered writes and removes the active transaction.
+func (t *Tx) Rollback() error {
+	e := t.engine
+	e.mu.Lock()
+	if e.closed {
+		e.mu.Unlock()
+		return ErrEngineClosed
+	}
+	if t.done {
+		e.mu.Unlock()
+		return ErrTxClosed
+	}
+	t.done = true
+	readOnly := t.readOnly
+	delete(e.active, t.beginID)
+	t.writes = nil
+	e.mu.Unlock()
+
+	if !readOnly {
+		e.logRollback(t.beginID)
+	}
+	return nil
+}
+
+func (e *Engine) logRollback(beginID uint64) {
+	idBuf := make([]byte, 8)
+	binary.LittleEndian.PutUint64(idBuf, beginID)
+	e.walMu.Lock()
+	_ = e.wal.append(0, recRollback, "", idBuf)
+	e.walMu.Unlock()
+}
*** End Patch
