+package kvstore
+
+import (
+	"bytes"
+	"errors"
+	"os"
+	"path/filepath"
+	"sync"
+	"testing"
+)
+
+func mustOpen(t *testing.T, dir string) *Engine {
+	t.Helper()
+	e, err := Open(dir)
+	if err != nil {
+		t.Fatalf("Open: %v", err)
+	}
+	return e
+}
+
+func tempDir(t *testing.T) string {
+	t.Helper()
+	dir, err := os.MkdirTemp("", "kvstore-")
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { os.RemoveAll(dir) })
+	return dir
+}
+
+func getOK(t *testing.T, tx *Tx, key, want string) {
+	t.Helper()
+	v, err := tx.Get(key)
+	if err != nil {
+		t.Fatalf("Get(%q): %v", key, err)
+	}
+	if string(v) != want {
+		t.Fatalf("Get(%q) = %q, want %q", key, v, want)
+	}
+}
+
+func getMissing(t *testing.T, tx *Tx, key string) {
+	t.Helper()
+	if _, err := tx.Get(key); !errors.Is(err, ErrKeyNotFound) {
+		t.Fatalf("Get(%q) err = %v, want ErrKeyNotFound", key, err)
+	}
+}
+
+func setCommit(t *testing.T, e *Engine, key, value string) {
+	t.Helper()
+	tx, err := e.Begin(false)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := tx.Set(key, []byte(value)); err != nil {
+		t.Fatal(err)
+	}
+	if err := tx.Commit(); err != nil {
+		t.Fatalf("Commit: %v", err)
+	}
+}
+
+// TestSnapshotIsolation verifies that a long-lived read transaction keeps
+// seeing its snapshot while concurrent write transactions commit.
+func TestSnapshotIsolation(t *testing.T) {
+	dir := tempDir(t)
+	e := mustOpen(t, dir)
+	defer e.Close()
+
+	setCommit(t, e, "a", "v1")
+
+	// Reader opens on the current snapshot.
+	r1, err := e.Begin(true)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer r1.Rollback()
+	getOK(t, r1, "a", "v1")
+
+	// Concurrent writer commits a new version after the reader began.
+	setCommit(t, e, "a", "v2")
+	getMissing(t, r1, "b")
+
+	getOK(t, r1, "a", "v1") // still the snapshot value
+
+	// A fresh reader sees v2.
+	r2, err := e.Begin(true)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer r2.Rollback()
+	getOK(t, r2, "a", "v2")
+
+	// New keys committed after r1 began must stay invisible to it.
+	setCommit(t, e, "b", "vb")
+	getMissing(t, r1, "b")
+	getOK(t, r2, "b", "vb")
+}
+
+// TestWriteConflict verifies first-committer-wins conflict detection.
+func TestWriteConflict(t *testing.T) {
+	dir := tempDir(t)
+	e := mustOpen(t, dir)
+	defer e.Close()
+
+	setCommit(t, e, "k", "init")
+
+	t1, err := e.Begin(false)
+	if err != nil {
+		t.Fatal(err)
+	}
+	t2, err := e.Begin(false)
+	if err != nil {
+		t.Fatal(err)
+	}
+
+	if err := t1.Set("k", []byte("from-t1")); err != nil {
+		t.Fatal(err)
+	}
+	if err := t2.Set("k", []byte("from-t2")); err != nil {
+		t.Fatal(err)
+	}
+
+	if err := t1.Commit(); err != nil {
+		t.Fatalf("first commit: %v", err)
+	}
+	if err := t2.Commit(); !errors.Is(err, ErrWriteConflict) {
+		t.Fatalf("second commit err = %v, want ErrWriteConflict", err)
+	}
+
+	// t2 must be finished (auto-rolled-back); reuse must fail.
+	if err := t2.Set("k", []byte("x")); !errors.Is(err, ErrTxClosed) {
+		t.Fatalf("post-conflict Set err = %v, want ErrTxClosed", err)
+	}
+
+	// t1's value is the winner.
+	r, err := e.Begin(true)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer r.Rollback()
+	getOK(t, r, "k", "from-t1")
+
+	// Disjoint keys do not conflict.
+	a, err := e.Begin(false)
+	if err != nil {
+		t.Fatal(err)
+	}
+	b, err := e.Begin(false)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := a.Set("x", []byte("1")); err != nil {
+		t.Fatal(err)
+	}
+	if err := b.Set("y", []byte("2")); err != nil {
+		t.Fatal(err)
+	}
+	if err := a.Commit(); err != nil {
+		t.Fatalf("a commit: %v", err)
+	}
