		e.walMu.Unlock()
		e.mu.Lock()
		t.done = true
		delete(e.active, t.beginID)
		e.mu.Unlock()
		return err
	}
	e.walMu.Unlock()

	// Publish under the write lock, coalescing repeated writes per key.
	e.mu.Lock()
	t.done = true
	delete(e.active, t.beginID)

