	binary.LittleEndian.PutUint64(idBuf, t.beginID)
	e.walMu.Lock()
	werr := e.wal.append(commitID, recCommit, "", idBuf)
	e.walMu.Unlock()
	if werr != nil {
		t.done = true
		delete(e.active, t.beginID)
		e.mu.Unlock()
		return werr
	}

